-- 增加项目访问、通知和资源库更新时间等状态，并维护相关查询和索引。
ALTER TABLE projects ADD COLUMN visited_at INTEGER NOT NULL DEFAULT 0;
CREATE INDEX projects_recent ON projects(visited_at DESC,id);
ALTER TABLE activity ADD COLUMN asset_id TEXT;
ALTER TABLE activity ADD COLUMN project_id TEXT;
CREATE INDEX activity_recent ON activity(id DESC);
CREATE TABLE notifications(id INTEGER PRIMARY KEY,at INTEGER NOT NULL,title TEXT NOT NULL,detail TEXT NOT NULL,level INTEGER NOT NULL CHECK(level BETWEEN 0 AND 2),asset_id TEXT,retry TEXT NOT NULL DEFAULT '',read_at INTEGER);
CREATE INDEX notifications_unread ON notifications(read_at,id);
CREATE TABLE library_state(id INTEGER PRIMARY KEY CHECK(id=1),updated_at INTEGER NOT NULL);
INSERT INTO library_state SELECT 1,coalesce(max(value),0) FROM (SELECT max(at) value FROM activity UNION ALL SELECT max(imported_at) FROM assets UNION ALL SELECT max(edited_at) FROM assets);
CREATE TRIGGER state_assets_insert AFTER INSERT ON assets BEGIN UPDATE library_state SET updated_at=max(updated_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE id=1; END;
CREATE TRIGGER state_assets_update AFTER UPDATE ON assets BEGIN UPDATE library_state SET updated_at=max(updated_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE id=1; END;
CREATE TRIGGER state_assets_delete AFTER DELETE ON assets BEGIN UPDATE library_state SET updated_at=max(updated_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE id=1; END;
CREATE TRIGGER state_asset_versions_insert AFTER INSERT ON asset_versions BEGIN UPDATE library_state SET updated_at=max(updated_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE id=1; END;
CREATE TRIGGER state_asset_versions_delete AFTER DELETE ON asset_versions BEGIN UPDATE library_state SET updated_at=max(updated_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE id=1; END;
CREATE TRIGGER state_projects_insert AFTER INSERT ON projects BEGIN UPDATE library_state SET updated_at=max(updated_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE id=1; END;
CREATE TRIGGER state_projects_delete AFTER DELETE ON projects BEGIN UPDATE library_state SET updated_at=max(updated_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE id=1; END;
CREATE TRIGGER state_project_assets_insert AFTER INSERT ON project_assets BEGIN UPDATE library_state SET updated_at=max(updated_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE id=1; END;
CREATE TRIGGER state_project_assets_delete AFTER DELETE ON project_assets BEGIN UPDATE library_state SET updated_at=max(updated_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE id=1; END;
CREATE TRIGGER state_asset_tags_insert AFTER INSERT ON asset_tags BEGIN UPDATE library_state SET updated_at=max(updated_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE id=1; END;
CREATE TRIGGER state_asset_tags_delete AFTER DELETE ON asset_tags BEGIN UPDATE library_state SET updated_at=max(updated_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE id=1; END;
CREATE TRIGGER state_tags_insert AFTER INSERT ON tags BEGIN UPDATE library_state SET updated_at=max(updated_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE id=1; END;
CREATE TRIGGER state_tags_update AFTER UPDATE ON tags BEGIN UPDATE library_state SET updated_at=max(updated_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE id=1; END;
CREATE TRIGGER state_tags_delete AFTER DELETE ON tags BEGIN UPDATE library_state SET updated_at=max(updated_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE id=1; END;
CREATE TRIGGER state_library_preferences_insert AFTER INSERT ON library_preferences BEGIN UPDATE library_state SET updated_at=max(updated_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE id=1; END;
CREATE TRIGGER state_library_preferences_update AFTER UPDATE ON library_preferences BEGIN UPDATE library_state SET updated_at=max(updated_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE id=1; END;
CREATE TRIGGER state_project_edit AFTER UPDATE OF name,parent_id ON projects BEGIN UPDATE library_state SET updated_at=max(updated_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE id=1; END;
CREATE TRIGGER activity_asset_import AFTER INSERT ON assets  BEGIN INSERT INTO activity(at,kind,detail,asset_id) VALUES(CAST(unixepoch('subsec')*1000 AS INTEGER),'import',new.name,new.id); END;
CREATE TRIGGER activity_asset_rename AFTER UPDATE OF name ON assets WHEN old.name<>new.name BEGIN INSERT INTO activity(at,kind,detail,asset_id) VALUES(CAST(unixepoch('subsec')*1000 AS INTEGER),'rename',new.name,new.id); END;
CREATE TRIGGER activity_asset_favorite AFTER UPDATE OF favorite ON assets WHEN old.favorite<>new.favorite BEGIN INSERT INTO activity(at,kind,detail,asset_id) VALUES(CAST(unixepoch('subsec')*1000 AS INTEGER),'favorite',new.name || CASE WHEN new.favorite=1 THEN ' · 已收藏' ELSE ' · 取消收藏' END,new.id); END;
CREATE TRIGGER activity_asset_rating AFTER UPDATE OF rating ON assets WHEN old.rating<>new.rating BEGIN INSERT INTO activity(at,kind,detail,asset_id) VALUES(CAST(unixepoch('subsec')*1000 AS INTEGER),'rating',new.name || ' · 评分 ' || new.rating,new.id); END;
CREATE TRIGGER activity_asset_notes AFTER UPDATE OF notes ON assets WHEN old.notes<>new.notes BEGIN INSERT INTO activity(at,kind,detail,asset_id) VALUES(CAST(unixepoch('subsec')*1000 AS INTEGER),'notes',new.name || ' · 更新备注',new.id); END;
CREATE TRIGGER activity_asset_trash AFTER UPDATE OF deleted_at ON assets WHEN old.deleted_at IS NOT new.deleted_at BEGIN INSERT INTO activity(at,kind,detail,asset_id) VALUES(CAST(unixepoch('subsec')*1000 AS INTEGER),'trash',new.name || CASE WHEN new.deleted_at IS NULL THEN ' · 已恢复' ELSE ' · 移入回收站' END,new.id); END;
CREATE TRIGGER activity_asset_purge AFTER DELETE ON assets  BEGIN INSERT INTO activity(at,kind,detail,asset_id) VALUES(CAST(unixepoch('subsec')*1000 AS INTEGER),'purge',old.name || ' · 永久删除',old.id); END;
CREATE TRIGGER activity_asset_tags_insert AFTER INSERT ON asset_tags BEGIN INSERT INTO activity(at,kind,detail,asset_id) VALUES(CAST(unixepoch('subsec')*1000 AS INTEGER),'tag',coalesce((SELECT name FROM assets WHERE id=new.asset_id),'素材') || ' · 添加归类',new.asset_id); END;
CREATE TRIGGER activity_asset_tags_delete AFTER DELETE ON asset_tags BEGIN INSERT INTO activity(at,kind,detail,asset_id) VALUES(CAST(unixepoch('subsec')*1000 AS INTEGER),'tag',coalesce((SELECT name FROM assets WHERE id=old.asset_id),'素材') || ' · 移除归类',old.asset_id); END;
CREATE TRIGGER activity_project_assets_insert AFTER INSERT ON project_assets BEGIN INSERT INTO activity(at,kind,detail,asset_id) VALUES(CAST(unixepoch('subsec')*1000 AS INTEGER),'membership',coalesce((SELECT name FROM assets WHERE id=new.asset_id),'素材') || ' · 添加归类',new.asset_id); END;
CREATE TRIGGER activity_project_assets_delete AFTER DELETE ON project_assets BEGIN INSERT INTO activity(at,kind,detail,asset_id) VALUES(CAST(unixepoch('subsec')*1000 AS INTEGER),'membership',coalesce((SELECT name FROM assets WHERE id=old.asset_id),'素材') || ' · 移除归类',old.asset_id); END;
CREATE TRIGGER activity_project_insert AFTER INSERT ON projects BEGIN INSERT INTO activity(at,kind,detail,project_id) VALUES(CAST(unixepoch('subsec')*1000 AS INTEGER),'project','创建项目 · ' || new.name,new.id); END;
CREATE TRIGGER activity_project_update AFTER UPDATE OF name,parent_id ON projects BEGIN INSERT INTO activity(at,kind,detail,project_id) VALUES(CAST(unixepoch('subsec')*1000 AS INTEGER),'project','编辑项目 · ' || new.name,new.id); END;
CREATE TRIGGER activity_project_delete AFTER DELETE ON projects BEGIN INSERT INTO activity(at,kind,detail,project_id) VALUES(CAST(unixepoch('subsec')*1000 AS INTEGER),'project','删除项目 · ' || old.name,old.id); END;
CREATE TRIGGER activity_version AFTER INSERT ON asset_versions WHEN new.origin<>'original' BEGIN INSERT INTO activity(at,kind,detail,asset_id) VALUES(CAST(unixepoch('subsec')*1000 AS INTEGER),'version','新增版本 · ' || new.origin,new.asset_id); END;
PRAGMA user_version=10;
